"""Chassis CSS: layout, nav, notes overlay, terminal panel, and the standard
slide-type library's styling. Content (colors aside) never lives here."""

BASE_CSS = """
*{margin:0;padding:0;box-sizing:border-box}html{font-size:calc(100vw / 120)}html,body{height:100%;background:#0a0a0a;color:#F0F4F8;font-family:'Red Hat Text',system-ui,sans-serif;overflow:hidden}
.slide{width:100vw;height:100vh;display:none;flex-direction:column;justify-content:center;padding:8vh 9vw;position:relative;overflow:hidden;transition:padding-right .25s ease-out}.slide.active{display:flex}
.slide::after{content:attr(data-footer);position:absolute;bottom:3vh;left:calc(9vw + 11.5rem);right:9vw;font-family:'Red Hat Mono',monospace;font-size:.7rem;color:#3a3a3a;border-top:1px solid #1a1a1a;padding-top:1vh}
body.term-open .slide{padding-right:52vw}
#progress{position:fixed;top:0;left:0;height:3px;background:#EE0000;width:0;z-index:60;transition:width .2s}
#nav{position:fixed;bottom:1.2rem;right:1.5rem;display:flex;gap:.5rem;align-items:center;z-index:70;font-family:'Red Hat Mono',monospace;font-size:.75rem;color:#555}#nav button{background:#151515;color:#aaa;border:1px solid #333;border-radius:4px;padding:.3rem .7rem;cursor:pointer;font-size:.9rem}#nav button:hover{color:#fff;border-color:#888}
.notes{display:none}.show-notes .notes{display:block;position:fixed;bottom:0;left:0;right:0;background:rgba(0,0,0,.93);border-top:2px solid #EE0000;padding:1.2vh 4vw;font-size:1.05rem;line-height:1.55;color:#ccc;max-height:24vh;overflow-y:auto;z-index:40}body.term-open .show-notes .notes{right:50%}.notes .say{color:#fff;margin:.3em 0}.notes .do{color:#f0ab00;font-family:'Red Hat Mono',monospace;font-size:.9em;margin:.4em 0 .4em 2.5em;padding-left:.8em;border-left:2px solid #f0ab00}.notes .cue{color:#8a949e;font-style:italic;font-size:.85em;margin:.4em 0 .4em 2.5em;padding-left:.8em;border-left:2px solid #333}
#term-panel{position:fixed;top:0;right:0;width:50vw;height:100vh;background:#000;border-left:2px solid #EE0000;transform:translateX(100%);transition:transform .25s ease-out;z-index:50;display:flex;flex-direction:column}#term-panel.open{transform:translateX(0)}#term-panel .term-header{display:flex;align-items:center;gap:1rem;padding:.5rem 1rem;background:#151515;font-family:'Red Hat Mono',monospace;font-size:.8rem;color:#aaa}#term-panel .term-tag{color:#EE0000;font-weight:700}#term-panel .term-close{margin-left:auto;background:none;border:1px solid #444;color:#aaa;padding:.2rem .6rem;cursor:pointer}#term-panel iframe{flex:1;border:0;background:#000}
body.presenter-child #term-panel,body.presenter-child #nav{display:none!important}
.logo{position:absolute;bottom:2.2vh;left:9vw;height:2.6rem;z-index:2}.logo img,.logo svg{height:2.6rem;width:auto}
.num{position:absolute;bottom:4vh;right:5vw;font-family:'Red Hat Mono',monospace;font-size:.7rem;color:#2a2a2a}
.kicker{font-size:.85rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:#EE0000;margin-bottom:1rem}
h1,h2{font-family:'Red Hat Display',sans-serif;font-weight:900;line-height:1.08}h2{font-size:2.7rem;max-width:82%;margin-bottom:1.4rem}h2 em,h1 em{color:#EE0000;font-style:normal}
.bar{width:72px;height:5px;background:#EE0000;margin:0 0 2rem}
.hint{position:fixed;bottom:1.5vh;left:50%;transform:translateX(-50%);font-family:'Red Hat Mono',monospace;font-size:.7rem;color:#222}
"""

SLIDE_TYPE_CSS = """
.s-title h1{font-size:3.6rem;max-width:80%}.s-title .sub{font-size:1.4rem;color:#9aa5b1;margin-top:1.6rem}.s-title .eyebrow{font-family:'Red Hat Mono',monospace;font-size:.85rem;color:#6a7580;letter-spacing:.08em;margin-bottom:1.4rem}
.s-title .plat{position:absolute;bottom:6vh;left:9vw;height:2.25rem}.s-title .plat img,.s-title .plat svg{height:2.25rem;width:auto}
.people{display:flex;gap:3rem;margin-top:2.6rem}.pname{font-weight:700;font-size:1.05rem}.prole{font-size:.9rem;color:#6a7580}
.pts{list-style:none;max-width:78%}.pts li{font-size:1.25rem;line-height:1.5;padding:.7rem 0 .7rem 1.4rem;border-left:3px solid #EE0000;margin-bottom:.9rem;color:#d6dce2}
.tl{display:grid;grid-template-columns:150px 1fr;row-gap:.9rem;column-gap:1.6rem;max-width:88%}.tl .d{font-family:'Red Hat Mono',monospace;color:#EE0000;font-weight:700;padding-top:.15rem}.tl .t{font-size:1.1rem;line-height:1.45;color:#d6dce2;border-bottom:1px solid #1c1c1c;padding-bottom:.8rem}
.cols{display:flex;gap:2rem}.col{flex:1;background:#111;border:1px solid #1e1e1e;border-top:3px solid #EE0000;padding:1.4rem 1.5rem}.col h3{font-family:'Red Hat Display',sans-serif;font-size:1.25rem;margin-bottom:.6rem}.col p{font-size:1.02rem;line-height:1.5;color:#c3cad1}.col .tag{font-family:'Red Hat Mono',monospace;font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:#6a7580;margin-bottom:.4rem}
.stats{display:flex;gap:2.4rem;margin:.5rem 0 1.8rem}.stat{flex:1}.stat .n{font-family:'Red Hat Display',sans-serif;font-size:3.4rem;font-weight:900;color:#EE0000;line-height:1}.stat .l{font-size:.98rem;color:#9aa5b1;margin-top:.5rem;line-height:1.4}
.foot{font-size:1.1rem;color:#d6dce2;line-height:1.5;max-width:80%;border-top:1px solid #1e1e1e;padding-top:1.2rem}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:1.2rem;max-width:92%}.cell{background:#111;border:1px solid #1e1e1e;padding:1.2rem 1.4rem}.cell h3{font-family:'Red Hat Display',sans-serif;font-size:1.15rem;margin-bottom:.4rem}.cell p{font-size:.98rem;color:#c3cad1;line-height:1.45}
.layers{display:flex;flex-direction:column;gap:.7rem;max-width:86%}.layer{display:grid;grid-template-columns:190px 1fr;gap:1.4rem;align-items:center;background:#111;border-left:4px solid #EE0000;padding:.85rem 1.2rem}.layer .n{font-family:'Red Hat Display',sans-serif;font-weight:700;font-size:1.1rem}.layer .t{font-size:1rem;color:#c3cad1;line-height:1.4}
.s-demo{background:#0d0d0d;align-items:flex-start}.badge{display:inline-block;font-family:'Red Hat Mono',monospace;font-size:.75rem;letter-spacing:.14em;text-transform:uppercase;color:#0a0a0a;background:#EE0000;padding:.35rem .7rem;margin-bottom:1.6rem}.dname{font-family:'Red Hat Display',sans-serif;font-size:3rem;font-weight:900;margin-bottom:.8rem}.dwhat{font-size:1.15rem;color:#9aa5b1;margin-bottom:2rem;max-width:80%}.chks{display:flex;gap:1rem;flex-wrap:wrap}.chk{font-family:'Red Hat Mono',monospace;font-size:.85rem;color:#c3cad1;border:1px solid #2a2a2a;padding:.5rem .9rem}
.hk{display:grid;grid-template-columns:1fr 300px;gap:2.4rem;max-width:94%}.htl{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;max-width:94%;margin-top:1.6rem;position:relative;padding-top:.9rem}.htl::before{content:'';position:absolute;left:0;right:0;top:.35rem;height:2px;background:#2a2a2a}.htl .hn2{position:relative;padding:0 .9rem 0 0}.htl .dot{position:absolute;top:-1rem;left:0;width:.8rem;height:.8rem;border-radius:50%;background:#EE0000}.htl .d{font-family:'Red Hat Mono',monospace;font-size:.78rem;color:#EE0000;font-weight:700;letter-spacing:.04em}.htl .t{font-size:.86rem;line-height:1.35;color:#b8c0c8;margin-top:.25rem}.hkt{font-family:'Red Hat Mono',monospace;font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:#EE0000;margin:.2rem 0 .4rem}.hkl p{font-size:1.05rem;line-height:1.5;color:#d6dce2;margin-bottom:1.1rem}.hkr{display:flex;flex-direction:column;gap:1.1rem;border-left:1px solid #1e1e1e;padding-left:1.8rem}.hn .n{font-family:'Red Hat Display',sans-serif;font-size:2.6rem;font-weight:900;color:#EE0000;line-height:1}.hn .l{font-size:.9rem;color:#9aa5b1;margin-top:.3rem;line-height:1.35}.s-hack h2{font-size:2.4rem;margin-bottom:1rem}
.s-teach{background:#0d0d0d}.lede{font-size:1.15rem;line-height:1.5;color:#9aa5b1;max-width:84%;margin:-.4rem 0 1.4rem}.s-teach .layer{grid-template-columns:260px 1fr}.s-teach .layer .n{font-size:1.02rem}
.wall{display:grid;grid-template-columns:repeat(7,1fr);gap:1rem;max-width:94%;margin-top:.4rem}.tile{height:92px;display:flex;align-items:center;justify-content:center;padding:14px 18px;background:#111;border:1px solid #1e1e1e}.tile.lt{background:#f4f4f4}.tile svg,.tile img{max-height:48px;max-width:100%;width:auto;height:auto}.wfoot{font-family:'Red Hat Mono',monospace;font-size:.72rem;color:#6a7580;margin-top:1.4rem}
.trend{display:grid;grid-template-columns:130px 1fr 1fr 1fr 1fr 1fr;gap:.5rem .9rem;max-width:94%;margin-top:.2rem}.trend .th{font-family:'Red Hat Display',sans-serif;font-weight:700;font-size:.9rem;color:#EE0000;padding:.3rem 0 .5rem;border-bottom:1px solid #2a2a2a}.trend .rl{font-family:'Red Hat Mono',monospace;font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;color:#6a7580;padding:.55rem 0}.trend .rc{font-size:.88rem;line-height:1.4;color:#d6dce2;background:#111;border-left:3px solid #1e1e1e;padding:.55rem .8rem}.trend .rc:nth-child(6n){border-left-color:#EE0000}
.s-close{background:#0a0a0a}.s-close .q{font-family:'Red Hat Display',sans-serif;font-size:2.2rem;font-weight:700;line-height:1.3;max-width:84%;color:#d6dce2}.s-close .punch{font-family:'Red Hat Display',sans-serif;font-size:3.4rem;font-weight:900;margin-top:2rem}.s-close .foot{margin-top:3rem;font-family:'Red Hat Mono',monospace;font-size:.9rem;color:#6a7580;border:0;padding:0}
"""

CHASSIS_CSS = BASE_CSS + SLIDE_TYPE_CSS
